digraph ModuleDependencies {
    rankdir=TB;

    // Global graph styling
    graph [
        fontname="Helvetica, Arial, sans-serif",
        fontsize=12,
        pad="0.5",
        nodesep="0.5",
        ranksep="0.6",
        bgcolor="transparent"
    ];

    // Default node styling
    node [
        fontname="Helvetica, Arial, sans-serif",
        fontsize=11,
        shape=box,
        style="rounded,filled",
        fillcolor="#f8fafc",
        color="#64748b",
        penwidth=1.5,
        margin="0.2,0.1"
    ];

    // Default edge styling
    edge [
        fontname="Helvetica, Arial, sans-serif",
        fontsize=10,
        color="#64748b",
        arrowsize=0.8,
        penwidth=1.2
    ];

    // Nodes
    ui         [label="ui", fillcolor="#e0f2fe", color="#0284c7"];
    api_client [label="api-client", fillcolor="#f0fdf4", color="#16a34a"];
    state      [label="state", fillcolor="#fef3c7", color="#d97706"];
    http       [label="http", fillcolor="#f1f5f9", color="#475569"];
    storage    [label="storage", fillcolor="#f1f5f9", color="#475569"];

    // Dependency relationships
    ui -> api_client;
    ui -> state;
    api_client -> http;
    state -> storage;
}

digraph Architecture {
    // General Graph Settings
    rankdir=TB;
    compound=true;
    fontname="Helvetica,Arial,sans-serif";
    node [fontname="Helvetica,Arial,sans-serif", fontsize=11];
    edge [fontname="Helvetica,Arial,sans-serif", fontsize=10, color="#64748B"];

    // External Client
    browser [
        label="Web Browser\n(Client)",
        shape=box,
        style="filled,rounded",
        fillcolor="#E0F2FE",
        color="#0284C7",
        penwidth=1.5
    ];

    // Frontend Cluster
    subgraph cluster_frontend {
        label = "Frontend";
        fontname = "Helvetica,Arial,sans-serif";
        fontsize = 13;
        fontcolor = "#0F172A";
        style = "filled,rounded";
        fillcolor = "#F1F5F9";
        color = "#CBD5E1";
        penwidth = 1.5;
        margin = 16;

        load_balancer [
            label="Load Balancer\n(Reverse Proxy)",
            shape=box,
            style="filled,rounded",
            fillcolor="#FFFFFF",
            color="#64748B",
            penwidth=1.5
        ];
    }

    // Backend Cluster
    subgraph cluster_backend {
        label = "Backend";
        fontname = "Helvetica,Arial,sans-serif";
        fontsize = 13;
        fontcolor = "#0F172A";
        style = "filled,rounded";
        fillcolor = "#F8FAFC";
        color = "#CBD5E1";
        penwidth = 1.5;
        margin = 16;

        api1 [
            label="API Server 1",
            shape=box,
            style="filled,rounded",
            fillcolor="#FEF3C7",
            color="#D97706",
            penwidth=1.5
        ];

        api2 [
            label="API Server 2",
            shape=box,
            style="filled,rounded",
            fillcolor="#FEF3C7",
            color="#D97706",
            penwidth=1.5
        ];

        database [
            label="Database\n(Shared)",
            shape=cylinder,
            style="filled",
            fillcolor="#DCFCE7",
            color="#16A34A",
            penwidth=1.5
        ];

        // Keep API servers on the same tier
        { rank = same; api1; api2; }
    }

    // Inter-component Connections
    browser -> load_balancer [label=" HTTP / HTTPS", penwidth=1.2];
    load_balancer -> api1 [label=" Distribute", penwidth=1.2];
    load_balancer -> api2 [label=" Distribute", penwidth=1.2];
    api1 -> database [label=" Read / Write", penwidth=1.2];
    api2 -> database [label=" Read / Write", penwidth=1.2];
}

