blockdiag {
  // Global settings
  default_fontsize = 12;
  default_shape = roundedbox;
  node_width = 130;
  node_height = 50;

  // Flow definition
  source -> compile -> test -> package -> publish;

  // Node styles
  source  [label = "Source\n(Git Commit)", color = "#E3F2FD", shape = ellipse];
  compile [label = "Compile\n(Build Step)", color = "#EDE7F6"];
  test    [label = "Test\n(Unit & Lint)", color = "#FFF9C4"];
  package [label = "Package\n(Docker / Jar)", color = "#E8F5E9"];
  publish [label = "Publish\n(Registry)", color = "#E0F2F1", shape = ellipse];
}

