skinparam conditionStyle inside
skinparam defaultTextAlignment center
skinparam shadowing false

start

:Receive return request and item;
:Check receipt and purchase date;

if (Receipt valid?) then (yes)
  :Inspect item condition;

  if (Item in acceptable condition?) then (yes)
    :Approve return;
    :Issue refund to customer;
    :Update inventory / Restock item;
    :Hand over refund receipt;
  else (no)
    :Explain condition failure to customer;
    :Reject return;
    :Return item back to customer;
  endif

else (no)
  :Explain receipt policy to customer;
  :Reject return;
endif

stop
@enduml

