  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "A bar chart showing fruit sales using inline data.",
  "width": 400,
  "height": 250,
  "padding": 5,

  "data": [
    {
      "name": "fruit_sales",
      "values": [
        {"fruit": "apples", "sales": 28},
        {"fruit": "pears", "sales": 55},
        {"fruit": "plums", "sales": 43}
      ]
    }
  ],

  "scales": [
    {
      "name": "xscale",
      "type": "band",
      "domain": {"data": "fruit_sales", "field": "fruit"},
      "range": "width",
      "padding": 0.25
    },
    {
      "name": "yscale",
      "type": "linear",
      "domain": {"data": "fruit_sales", "field": "sales"},
      "range": "height",
      "nice": true,
      "zero": true
    }
  ],

  "axes": [
    {
      "orient": "bottom",
      "scale": "xscale",
      "title": "Fruit"
    },
    {
      "orient": "left",
      "scale": "yscale",
      "title": "Sales"
    }
  ],

  "marks": [
    {
      "type": "rect",
      "from": {"data": "fruit_sales"},
      "encode": {
        "enter": {
          "x": {"scale": "xscale", "field": "fruit"},
          "width": {"scale": "xscale", "band": 1},
          "y": {"scale": "yscale", "field": "sales"},
          "y2": {"scale": "yscale", "value": 0},
          "fill": {"value": "#4c78a8"}
        },
        "hover": {
          "fill": {"value": "#305d8c"}
        },
        "update": {
          "fill": {"value": "#4c78a8"}
        }
      }
    }
  ]
}

